    Bug 1953596 - Account Hub Fix incorrect error handling on account creation failure. r=aleca


    **How to Test**
    - Use the test account testaccounts@o365.thunderbird.net
    - Skip the auth modal
    - Select exchange (not the add-on one)
    - Click continue
    - Close auth modal
    - You should see the correct notification title and details with the actual error message

    Differential Revision: https://phabricator.services.mozilla.com/D241460

diff --git a/mail/components/accountcreation/content/widgets/account-hub-header.mjs b/mail/components/accountcreation/content/widgets/account-hub-header.mjs
index 489cb8ea874..62a2aa33b69 100644
--- a/mail/components/accountcreation/content/widgets/account-hub-header.mjs
+++ b/mail/components/accountcreation/content/widgets/account-hub-header.mjs
@@ -57,7 +57,7 @@ class AccountHubHeader extends HTMLElement {
    *   to localize for the title.
    * @param {string} options.fluentDescriptionId - A string representing a
    *   fluent id to localize for the description.
-   * @param {string} options.title - A raw string to displayin the description.
+   * @param {string} options.title - A raw string to display in the description.
    * @param {string} options.type - The type of notification (error, success, info,
    *   warning).
    */
@@ -113,6 +113,10 @@ class AccountHubHeader extends HTMLElement {
         descriptionElement.querySelector(".localized-description"),
         fluentDescriptionId || error.cause.fluentDescriptionId
       );
+
+      // If we have a specific fluent ID for the description, return early
+      // so we don't have two descriptions.
+      return;
     }

     if (description || (type === "error" && error?.message)) {
@@ -147,6 +151,10 @@ class AccountHubHeader extends HTMLElement {
         titleElement.querySelector(".localized-title"),
         localizedTitle
       );
+
+      // If we have a localized title, return early so we don't have two
+      // titles.
+      return;
     }

     if (title) {
diff --git a/mail/components/accountcreation/views/email.mjs b/mail/components/accountcreation/views/email.mjs
index f2824c4457e..3fa9657ebd2 100644
--- a/mail/components/accountcreation/views/email.mjs
+++ b/mail/components/accountcreation/views/email.mjs
@@ -472,6 +472,7 @@ class AccountHubEmail extends HTMLElement {
           this.#currentSubview.showNotification({
             title: error.title || error.message,
             description: error.text,
+            error,
             type: "error",
           });
         }
@@ -1096,7 +1097,7 @@ class AccountHubEmail extends HTMLElement {
       Glean.mail.successfulEmailAccountSetup[telemetryKey].add(1);
     } catch (error) {
       // If we get no message, then something other than VerifyLogon failed.
-
+      let errorTitle = "account-hub-account-authentication-error";
       // For an Exchange server, some known configurations can
       // be disabled (per user or domain or server).
       // Warn the user if the open protocol we tried didn't work.
@@ -1104,13 +1105,17 @@ class AccountHubEmail extends HTMLElement {
         ["imap", "pop3"].includes(completeConfig.incoming.type) &&
         completeConfig.incomingAlternatives.some(i => i.type == "exchange")
       ) {
-        error.cause.fluentTitleId =
-          "account-setup-exchange-config-unverifiable";
+        errorTitle = "account-setup-exchange-config-unverifiable";
       }

       this.#configVerifier.cleanup();
       Glean.mail.failedEmailAccountSetup[telemetryKey].add(1);
-      throw error;
+
+      throw new Error(error.message, {
+        cause: {
+          fluentTitleId: errorTitle,
+        },
+      });
     }
   }

